// Type descriptors and value types used by TypeScript generated by DotAsn (asn1 generate-typescript).
//
// A descriptor tells the value-notation conversion (json.ts) how a type's values look in TypeScript. Encoding is done
// by @dotasn/wasm, which loads the full description of the types from the generated schema (dotasn-schema.ts).

/** Returns a type descriptor; used for references so that recursive and out-of-order definitions work. */
export type Lazy = () => Asn1Type;

interface Base<K extends string> {
  readonly kind: K;
  /** The ASN.1 name (Module.Type for assignments, the built-in name otherwise). */
  readonly name: string;
}

export interface BooleanType extends Base<'boolean'> {}

export interface IntegerType extends Base<'integer'> {
  /** Values are bigint (true) or number (false, values within ±(2^53 − 1)). */
  readonly big: boolean;
}

export interface EnumeratedType extends Base<'enumerated'> {
  /** The identifiers of the root items and extension additions. */
  readonly items: readonly string[];
}

export interface RealType extends Base<'real'> {}

export interface BitStringType extends Base<'bitString'> {
  /** Named bits: identifier to bit position. */
  readonly named?: Readonly<Record<string, number>>;
}

export interface OctetStringType extends Base<'octetString'> {}

export interface NullType extends Base<'null'> {}

export interface ObjectIdentifierType extends Base<'objectIdentifier'> {}

export interface RelativeOidType extends Base<'relativeOid'> {}

/** All character string types; values are strings. */
export interface CharacterStringType extends Base<'string'> {}

/** UTCTime, GeneralizedTime and the X.680 time types; values are strings. */
export interface TimeType extends Base<'time'> {}

export interface Component {
  /** The ASN.1 identifier, which is also the property name of the value object. */
  readonly name: string;
  readonly type: Lazy;
  /** True for OPTIONAL and DEFAULT components and extension additions, which may be absent. */
  readonly optional?: boolean;
}

export interface SequenceType extends Base<'sequence' | 'set'> {
  readonly components: readonly Component[];
}

export interface CollectionType extends Base<'sequenceOf' | 'setOf'> {
  readonly element: Lazy;
}

export interface Alternative {
  readonly name: string;
  readonly type: Lazy;
}

export interface ChoiceType extends Base<'choice'> {
  readonly alternatives: readonly Alternative[];
}

export interface OpenType extends Base<'open'> {}

/** A resolved descriptor. */
export type Descriptor =
  | BooleanType | IntegerType | EnumeratedType | RealType | BitStringType | OctetStringType | NullType
  | ObjectIdentifierType | RelativeOidType | CharacterStringType | TimeType | SequenceType | CollectionType
  | ChoiceType | OpenType;

/** A named alias of another type (B ::= A): the values of the target under its own name. */
export interface RefType {
  readonly kind: 'ref';
  readonly name: string;
  readonly target: Lazy;
}

declare const valueType: unique symbol;

/** A type descriptor whose values have the TypeScript type T. */
export type Asn1Type<T = unknown> = (Descriptor | RefType) & { readonly [valueType]?: T };

// ------------------------------------------------------------------ values

/** A BIT STRING value: `length` bits, most significant bit of `bytes[0]` first, unused trailing bits zero. */
export interface BitString {
  readonly bytes: Uint8Array;
  readonly length: number;
}

/** An open type value: either a typed value or the raw encoding (as decoded). */
export type OpenValue =
  | { readonly type: Asn1Type; readonly value: unknown }
  | { readonly encoded: Uint8Array; readonly rule: string };

/** An ENUMERATED item from a later version of the type (decoding only; it cannot be encoded). */
export interface UnknownEnumItem {
  /** The PER extension index of the item, or -1 for encodings that do not carry one (BER, OER, JER, XER). */
  readonly $unknown: number;
}

/** A CHOICE alternative from a later version of the type, kept as its raw encoding so it can be relayed. */
export interface UnknownAlternative {
  readonly $unknownExtension: {
    readonly encoded: Uint8Array;
    readonly rule: string;
    /** The PER extension index, or -1. */
    readonly index: number;
  };
}

// ------------------------------------------------------------------ resolution

const resolved = new WeakMap<object, Descriptor>();

/** Resolves aliases (memoized) and returns the effective descriptor, named after the alias. */
export function resolve(type: Asn1Type): Descriptor {
  if (type.kind !== 'ref') {
    return type;
  }

  let d = resolved.get(type);
  if (d === undefined) {
    d = { ...resolve(type.target()), name: type.name };
    resolved.set(type, d);
  }

  return d;
}

const lazyCache = new WeakMap<object, Descriptor>();

/** The resolved type of a component or alternative (memoized per component). */
export function typeOf(member: Component | Alternative): Descriptor {
  let d = lazyCache.get(member);
  if (d === undefined) {
    d = resolve(member.type());
    lazyCache.set(member, d);
  }

  return d;
}

/** The resolved element type of a collection (memoized). */
export function elementOf(collection: CollectionType): Descriptor {
  let d = lazyCache.get(collection);
  if (d === undefined) {
    d = resolve(collection.element());
    lazyCache.set(collection, d);
  }

  return d;
}
